@import url('https://fonts.googleapis.com/css2?family=Baloo+2:wght@500;600;700;800&family=Nunito:wght@600;700;800;900&display=swap');
:root{--ink:#17254a;--orange:#ff6547;--yellow:#ffe169;--cream:#fff8e9;--blue:#6ecbdb}
*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#9bd9dc;font-family:'Nunito',system-ui,sans-serif;color:var(--ink)}button{font:inherit}.game-shell{position:relative;width:100vw;height:100dvh;min-height:480px;overflow:hidden;background:#a5e0dc;isolation:isolate}#game{position:absolute;inset:0;width:100%;height:100%;display:block}.game-shell:after{content:'';position:absolute;inset:0;pointer-events:none;z-index:0;background:linear-gradient(180deg,rgba(255,244,198,.17),transparent 30%,rgba(39,44,65,.09));}.topbar{position:absolute;z-index:2;top:max(20px,env(safe-area-inset-top));left:clamp(18px,4vw,58px);right:clamp(18px,4vw,58px);display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:10px;color:#213452;text-decoration:none;font-size:12px;font-weight:1000;letter-spacing:1.6px}.brand i{font-style:normal;color:var(--orange)}.brand-mark{display:grid;place-items:center;width:34px;height:34px;border:2px solid #203653;background:#ffdd61;border-radius:12px;font-family:'Baloo 2',sans-serif;font-size:23px;box-shadow:2px 3px 0 #203653;transform:rotate(-5deg)}.top-right{display:flex;align-items:center;gap:10px}.sound-label{font-size:10px;letter-spacing:1.5px;font-weight:900;margin-right:-4px}.icon-btn{width:37px;height:37px;background:rgba(255,251,232,.88);border:1.5px solid #273b55;border-radius:12px;box-shadow:2px 3px 0 #273b55;color:#273b55;font-weight:1000;cursor:pointer;font-size:17px}.icon-btn:hover{transform:translateY(-2px)}.hud{position:absolute;z-index:2;top:82px;left:clamp(18px,4vw,58px);right:clamp(18px,4vw,58px);display:flex;align-items:center;gap:20px;pointer-events:none}.hud[hidden],.screen[hidden],.mobile-controls[hidden]{display:none}.hud-stat{background:#fff7dd;border:2px solid #223653;border-radius:14px;box-shadow:3px 4px 0 #223653;padding:8px 14px;min-width:104px;display:grid;grid-template-columns:auto auto;align-items:end;column-gap:5px}.eyebrow{font-size:9px;letter-spacing:1.5px;font-weight:1000;color:#6b6d6a}.hud-stat .eyebrow{grid-column:1/-1}.hud-stat strong{font-family:'Baloo 2';font-size:26px;line-height:1}.hud-stat small{font-weight:900;font-size:11px}.treat-stat{display:flex;gap:7px;align-items:center;min-width:115px}.treat-stat .eyebrow{font-size:9px;line-height:1.1;max-width:48px}.treat-stat strong{font-size:23px}.treat-icon{font-size:22px;color:#f5aa13;text-shadow:1px 2px #bd7318}.mom-meter{margin-left:auto;display:flex;align-items:center;gap:8px;width:210px;padding:8px 11px;background:rgba(255,247,221,.93);border:2px solid #233653;border-radius:14px;box-shadow:3px 4px 0 #233653}.mom-avatar{font-size:23px}.meter-copy{flex:1}.meter-track{height:8px;margin-top:3px;border-radius:8px;background:#f2c9b9;overflow:hidden;border:1px solid #d5a28f}.meter-track i{display:block;width:40%;height:100%;background:#ff6b52;border-radius:8px;transition:width .2s}.meter-emoji{font-size:20px}.screen{position:absolute;z-index:3;inset:0;display:grid;place-items:center;padding:80px 24px 48px;background:linear-gradient(90deg,rgba(255,232,167,.98) 0%,rgba(255,235,174,.91) 42%,rgba(255,234,170,.15) 74%,transparent 100%)}.welcome{display:block}.welcome-copy{position:absolute;top:50%;left:clamp(42px,10vw,150px);transform:translateY(-44%);z-index:2;max-width:495px}.kicker{display:flex;align-items:center;gap:9px;color:#5d5a52;font-size:12px;letter-spacing:1.9px;text-transform:uppercase;font-weight:1000}.kicker b{color:#f5ac27}.welcome h1{font-family:'Baloo 2',sans-serif;font-weight:800;font-size:clamp(57px,8.5vw,112px);line-height:.77;letter-spacing:-4px;margin:17px 0 15px;color:#213452;text-shadow:4px 5px 0 rgba(255,255,255,.55);transform:rotate(-2deg)}.welcome h1 em{font-style:normal;color:#ff6448;-webkit-text-stroke:1px #fff3cf;text-shadow:4px 5px 0 #213452;letter-spacing:-3px}.subtitle{font-size:18px;margin:25px 0 7px;font-weight:800}.subtitle strong{font-weight:1000;color:#ed6047}.intro{font-size:14px;line-height:1.6;color:#535d63;margin:0 0 19px;font-weight:700}.play-btn{display:flex;align-items:center;justify-content:space-between;gap:24px;padding:0 10px 0 23px;min-width:192px;height:54px;border:2px solid #223653;border-radius:16px;background:#ff684d;color:white;box-shadow:4px 5px 0 #223653;cursor:pointer;font-size:14px;font-weight:1000;letter-spacing:1px;transition:transform .15s,box-shadow .15s}.play-btn b{display:grid;place-items:center;width:34px;height:34px;background:#ffd75a;color:#243753;border:1.5px solid #223653;border-radius:11px;font-size:21px}.play-btn:hover{transform:translate(2px,2px);box-shadow:2px 3px 0 #223653}.controls-hint{margin-top:22px;color:#66706b;font-size:9px;font-weight:1000;letter-spacing:1.15px}.controls-hint span{display:inline-grid;place-items:center;min-width:21px;height:20px;padding:0 4px;border:1.5px solid #263852;border-radius:5px;color:#263852;background:#fff9e7;font-size:11px;margin-right:4px;box-shadow:1px 2px 0 #263852}.controls-hint i{padding:0 4px;color:#ed765b;font-style:normal}.hero-art{position:absolute;right:5%;top:48%;width:min(48vw,600px);height:min(68vh,560px);transform:translateY(-43%);z-index:1}.hero-shin{position:absolute;z-index:2;right:28%;bottom:16%;font-size:clamp(110px,22vw,270px);filter:drop-shadow(8px 13px 0 rgba(36,48,59,.16));transform:rotate(-9deg)}.hero-shiro{position:absolute;z-index:3;right:5%;bottom:10%;font-size:clamp(70px,13vw,150px);filter:drop-shadow(6px 9px 0 rgba(36,48,59,.16));transform:rotate(8deg)}.hero-mom{position:absolute;right:-2%;bottom:28%;z-index:1;font-size:clamp(65px,12vw,135px);filter:drop-shadow(5px 8px 0 rgba(36,48,59,.15));transform:rotate(-14deg)}.hero-shout{position:absolute;top:11%;left:12%;z-index:3;background:white;border:2px solid #213452;border-radius:50%;padding:14px 20px;font-family:'Baloo 2';font-weight:800;font-size:22px;transform:rotate(-8deg);box-shadow:3px 4px #213452}.hero-shout:after{content:'';position:absolute;bottom:-8px;left:24px;width:14px;height:14px;background:white;border-right:2px solid #213452;border-bottom:2px solid #213452;transform:rotate(35deg)}.speed-lines{position:absolute;inset:15% 2% 5%;border-radius:50%;background:repeating-conic-gradient(from 25deg at 52% 55%,transparent 0deg 8deg,rgba(255,255,255,.5) 8.3deg 9deg,transparent 9.5deg 19deg);mask-image:radial-gradient(ellipse,transparent 25%,black 68%,transparent 70%)}.corner-note{position:absolute;bottom:31px;left:clamp(42px,10vw,150px);font-size:9px;letter-spacing:2.1px;font-weight:1000;color:#77745e}.game-footer{position:absolute;z-index:2;bottom:max(16px,env(safe-area-inset-bottom));left:clamp(18px,4vw,58px);right:clamp(18px,4vw,58px);display:flex;justify-content:space-between;color:rgba(31,51,75,.7);font-size:9px;letter-spacing:1.4px;font-weight:1000;pointer-events:none}.game-footer b{color:#233b56}.toast{position:absolute;z-index:4;left:50%;top:25%;transform:translate(-50%,-10px);opacity:0;padding:9px 17px;border-radius:30px;background:#fff7db;border:2px solid #213653;box-shadow:3px 4px #213653;font-weight:1000;letter-spacing:.7px;transition:all .22s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.pause-screen,.result-screen{background:rgba(29,45,63,.3);backdrop-filter:blur(4px);place-items:center}.dialog-card{width:min(420px,92vw);text-align:center;padding:34px 32px 30px;background:#fff5da;border:2px solid #213653;border-radius:26px;box-shadow:8px 9px 0 rgba(32,50,73,.8);position:relative}.dialog-sticker{display:grid;place-items:center;width:69px;height:69px;border-radius:21px;background:#ffe06a;border:2px solid #213653;font-size:37px;margin:-68px auto 15px;box-shadow:3px 4px #213653;transform:rotate(-7deg)}.dialog-card .kicker{justify-content:center}.dialog-card h2{font-family:'Baloo 2';font-size:35px;line-height:1.05;margin:6px 0;color:#213653}.dialog-card>p:not(.kicker){font-size:14px;color:#69716c;font-weight:700}.dialog-card .play-btn{margin:21px auto 0}.result-stats{display:flex;justify-content:center;gap:12px;margin:18px auto}.result-stats div{display:grid;gap:0;min-width:108px;padding:9px;border-radius:12px;background:#ffe8a5;border:1.5px solid #213653}.result-stats strong{font-family:'Baloo 2';font-size:24px}.result-stats span{font-size:9px;font-weight:1000;letter-spacing:1.2px;color:#71736b}.mobile-controls{position:absolute;z-index:3;bottom:56px;left:50%;transform:translateX(-50%);display:flex;gap:10px}.mobile-controls button{width:49px;height:48px;border:2px solid #213653;border-radius:14px;background:rgba(255,247,221,.9);box-shadow:3px 4px #213653;color:#213653;font-weight:1000;font-size:17px;touch-action:none}.mobile-controls button:active{transform:translateY(3px);box-shadow:0 1px #213653}
@media(max-width:760px){.topbar{top:max(14px,env(safe-area-inset-top))}.brand{font-size:10px}.sound-label{display:none}.hud{top:68px;gap:8px}.hud-stat{padding:6px 9px;min-width:78px;border-radius:11px}.hud-stat strong{font-size:21px}.treat-stat{min-width:91px;gap:5px}.treat-stat .eyebrow{font-size:7px}.mom-meter{width:145px;padding:6px 8px;gap:5px}.mom-avatar{font-size:18px}.meter-emoji{font-size:16px}.eyebrow{font-size:7px}.welcome{background:linear-gradient(180deg,rgba(255,232,167,.97) 0%,rgba(255,235,174,.87) 46%,rgba(255,234,170,.03) 100%)}.welcome-copy{top:13%;left:8%;transform:none}.welcome h1{font-size:clamp(54px,14vw,90px);margin:13px 0 10px}.subtitle{font-size:15px;margin-top:14px}.intro{font-size:12px;margin-bottom:12px}.play-btn{height:47px;min-width:170px}.controls-hint{margin-top:15px;font-size:8px}.hero-art{width:85vw;height:45vh;right:-2%;top:auto;bottom:7%;transform:none}.hero-shin{font-size:clamp(125px,39vw,220px);right:34%;bottom:4%}.hero-shiro{font-size:clamp(73px,22vw,125px);right:9%;bottom:3%}.hero-mom{font-size:clamp(72px,21vw,120px);right:-5%;bottom:23%}.hero-shout{font-size:17px;top:0;left:9%;padding:8px 13px}.corner-note{left:8%;bottom:19px;font-size:7px}.game-footer{bottom:max(12px,env(safe-area-inset-bottom));font-size:7px}.mobile-controls{bottom:max(51px,calc(env(safe-area-inset-bottom) + 46px));gap:7px}.mobile-controls button{width:44px;height:43px}.screen:not(.welcome){padding-bottom:85px}}
@media(max-height:650px) and (min-width:761px){.welcome-copy{left:8%;transform:translateY(-45%) scale(.86);transform-origin:left center}.hero-art{height:77vh}.hero-shin{font-size:clamp(120px,22vh,220px)}.corner-note{left:8%}}
